class LmdbDeferredLearnedFeedbackRegressionTest {

	private static final String QUERY = """
			SELECT * WHERE {
				?person <urn:test:memberOf> ?organization .
				?person <urn:test:score> ?score .
				FILTER(?score = 5)
			}
			""";

	@Test
	void statisticsCreatedBeforePublicationCanLearnAfterPublication(
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		LmdbStore store = new HeldStore(directory, entered, release);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			assertTrue(entered.await(10, TimeUnit.SECONDS), "the real post-ready worker must be held");
			LmdbEvaluationStatistics early = (LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics();
			early.bindExecutionSnapshot(OptionalLong.of(early.estimatorRuntime().snapshotVersion()));
			assertNotEquals(EvaluationStatistics.FilterPassEstimate.Source.LEARNED_FILTER,
					early.estimateFilterPass(filter()).getSource());
			release.countDown();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			early.recordFilterOutcome(filter(), 20L, 80L);
			EvaluationStatistics.FilterPassEstimate oldObject = early.estimateFilterPass(filter());
			EvaluationStatistics.FilterPassEstimate newObject = store.getBackingStore()
					.getEvaluationStatistics().estimateFilterPass(filter());
			assertEquals(EvaluationStatistics.FilterPassEstimate.Source.LEARNED_FILTER, oldObject.getSource(),
					"a query-owned statistics instance must see its committed observation after publication");
			assertEquals(EvaluationStatistics.FilterPassEstimate.Source.LEARNED_FILTER, newObject.getSource(),
					"the store's later query must see the same observation");
			assertEquals(0.2d, newObject.getPassRatio(), 0.000_001d);
			assertEquals(100L, newObject.getEvidenceCount());
		} finally {
			release.countDown();
			repository.shutDown();
		}
	}


	@Test
	void freshFacadeLearnsAfterPublication(@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		LmdbStore store = new HeldStore(directory, entered, release);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			assertTrue(entered.await(10, TimeUnit.SECONDS), "the real post-ready worker must be held");
			release.countDown();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			LmdbEvaluationStatistics fresh = (LmdbEvaluationStatistics) store.getBackingStore().getEvaluationStatistics();
			fresh.bindExecutionSnapshot(OptionalLong.of(fresh.estimatorRuntime().snapshotVersion()));
			fresh.recordFilterOutcome(filter(), 20L, 80L);
			assertEquals(EvaluationStatistics.FilterPassEstimate.Source.LEARNED_FILTER,
					fresh.estimateFilterPass(filter()).getSource(), "the observation and filter must be eligible");
		} finally {
			release.countDown();
			repository.shutDown();
		}
	}

	@Test
	void priorSnapshotObservationRemainsUnavailableAfterMutation(
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		LmdbStore store = new HeldStore(directory, entered, release);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			assertTrue(entered.await(10, TimeUnit.SECONDS), "the real post-ready worker must be held");
			LmdbEvaluationStatistics early = (LmdbEvaluationStatistics) store.getBackingStore().getEvaluationStatistics();
			long oldEpoch = early.estimatorRuntime().snapshotVersion();
			early.bindExecutionSnapshot(OptionalLong.of(oldEpoch));
			try (var connection = repository.getConnection()) {
				var values = connection.getValueFactory();
				connection.add(values.createIRI("urn:test:person"), values.createIRI("urn:test:score"),
						values.createLiteral(5));
			}
			assertNotEquals(oldEpoch, early.estimatorRuntime().snapshotVersion(), "the committed data revision must advance");
			release.countDown();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			early.recordFilterOutcome(filter(), 20L, 80L);
			assertNotEquals(EvaluationStatistics.FilterPassEstimate.Source.LEARNED_FILTER,
					store.getBackingStore().getEvaluationStatistics().estimateFilterPass(filter()).getSource(),
					"an observation from a prior snapshot cannot train current data");
		} finally {
			release.countDown();
			repository.shutDown();
		}
	}

	private static Filter filter() {
		TupleExpr root = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, QUERY, null).getTupleExpr();
		PlanningGraphDomains.capture(root, PlanningGraphDomain.defaultGraph());
		Filter[] found = new Filter[1];
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Filter filter) {
				if (found[0] == null) {
					found[0] = filter;
				}
				super.meet(filter);
			}
		});
		return found[0];
	}

	private static final class HeldStore extends LmdbStore {
		private final CountDownLatch entered;
		private final CountDownLatch release;

		private HeldStore(Path directory, CountDownLatch entered, CountDownLatch release) {
			super(directory.toFile(), new LmdbStoreConfig("spoc,posc"));
			this.entered = entered;
			this.release = release;
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketches) throws IOException, SailException {
			return new LmdbSailStore(directory, properties, config, sketches, null,
					(tripleDir, props, settings, values) -> new TripleStore(tripleDir, props, settings, values) {
						@Override
						void startBackgroundIndexRebuild() {
							entered.countDown();
							try {
								release.await();
							} catch (InterruptedException failure) {
								Thread.currentThread().interrupt();
								return;
							}
							super.startBackgroundIndexRebuild();
						}
					});
		}
	}
}
